mapper.select:
SELECT SIMULATION_ID AS "simulationId", SIMULATION_NO AS "simulationNo", SIMULATION_NAME AS "simulationName", MODEL_ID AS "modelId", SCHEME_ID AS "schemeId", SIMULATION_SCENARIO AS "simulationScenario", ESTIMATED_COST AS "estimatedCost", CONFIDENCE_LEVEL AS "confidenceLevel", SIMULATION_STATUS AS "simulationStatus", EXECUTION_TIME AS "executionTime", CREATE_TIME AS "createTime" FROM TBL_COST_SIMULATION WHERE BOOK_ID = #{bookId} AND TENANT_ID = #{tenantId}
AND SIMULATION_NO LIKE '%' || #{simulationNo} || '%'
AND SIMULATION_NAME LIKE '%' || #{simulationName} || '%'
AND MODEL_ID = #{modelId}
AND SIMULATION_STATUS = #{simulationStatus}
ORDER BY CREATE_TIME DESC OFFSET #{offset} ROWS FETCH NEXT #{pageSize} ROWS ONLY

SELECT COUNT(1)
FROM TBL_COST_SIMULATION
WHERE BOOK_ID = #{bookId}
  AND TENANT_ID = #{tenantId}

      AND SIMULATION_NO LIKE '%' || #{simulationNo} || '%'


      AND SIMULATION_NAME LIKE '%' || #{simulationName} || '%'


      AND MODEL_ID = #{modelId}


      AND SIMULATION_STATUS = #{simulationStatus}

SELECT
    COUNT(1) AS "totalCount",
    SUM(CASE WHEN SIMULATION_STATUS = 2 THEN 1 ELSE 0 END) AS "completedCount",
    AVG(ESTIMATED_COST) AS "avgCost",
    AVG(CONFIDENCE_LEVEL) AS "avgConfidence"
FROM TBL_COST_SIMULATION
WHERE MODEL_ID = #{modelId}
  AND BOOK_ID = #{bookId}
  AND TENANT_ID = #{tenantId}
